import numpy as np

def q_update(Q, s, a, r, s2, done, alpha, gamma):
    target = r if done else r + gamma * np.max(Q[s2])
    Q[s, a] += alpha * (target - Q[s, a])
    return Q

def choose(q_row, eps, rng):
    u = rng.random()
    if u < eps:
        return int(rng.integers(len(q_row)))
    return int(np.argmax(q_row))

def step(s, a):
    r, c = divmod(s, 4)
    dr, dc = [(-1, 0), (0, 1), (1, 0), (0, -1)][a]
    r2, c2 = min(max(r + dr, 0), 3), min(max(c + dc, 0), 3)
    s2 = r2 * 4 + c2
    if s2 == 15:
        return s2, 1.0, True
    return s2, -0.01, False

def train(episodes=300, alpha=0.5, gamma=0.9, eps=0.2, seed=0):
    rng = np.random.default_rng(seed)
    Q = np.zeros((16, 4))
    for ep in range(episodes):
        s = 0
        for t in range(100):
            a = choose(Q[s], eps, rng)
            s2, r, done = step(s, a)
            q_update(Q, s, a, r, s2, done, alpha, gamma)
            s = s2
            if done:
                break
    return Q
